/// Postgres keyword category for a lowercase word, if it is one.
pub fn pg_keyword_category(word: &str) -> Option<PgKeywordCategory> {
	PG_KEYWORDS
		.binary_search_by(|(kw, _)| kw.cmp(&word))
		.ok()
		.map(|index| PG_KEYWORDS[index].1)
}

/// Is this word (compared ASCII-case-insensitively) a SQLite keyword?
pub fn is_sqlite_keyword(word: &str) -> bool {
	let lower = word.to_ascii_lowercase();
	SQLITE_KEYWORDS.binary_search(&lower.as_str()).is_ok()
}
